// ---- reset -----------------------------------------------------------------------------------

async function withDedicatedConnection<T>(conn: Connection | Pool, fn: (c: Connection | PoolConnection) => Promise<T>): Promise<T> {
  // FOREIGN_KEY_CHECKS is per session, so a pool has to lend one connection for the whole reset.
  if ("getConnection" in conn && typeof conn.getConnection === "function") {
    const c = await (conn as Pool).getConnection();
    try {
      return await fn(c);
    } finally {
      c.release();
    }
  }
  return fn(conn as Connection);
}

async function resetData(conn: Connection | Pool): Promise<void> {
  await withDedicatedConnection(conn, async (c) => {
    const [rows] = await c.query<RowDataPacket[]>("SHOW TABLES");
    const existing = new Set(rows.map((r) => String(Object.values(r)[0])));
    await c.query("SET FOREIGN_KEY_CHECKS = 0");
    try {
      for (const t of RESET_TABLES) {
        if (!existing.has(t)) continue; // e.g. `debts`, dropped on installs past migration 0008
        await c.query(`DELETE FROM \`${t}\``);
        // Cosmetic (ids restart at 1); a runtime user without ALTER just keeps counting.
        await c.query(`ALTER TABLE \`${t}\` AUTO_INCREMENT = 1`).catch(() => {});
      }
      if (existing.has("app_settings")) {
        await c.query("DELETE FROM `app_settings` WHERE `setting_key` NOT IN (?)", [PRESERVED_SETTING_KEYS]);
      }
    } finally {
      await c.query("SET FOREIGN_KEY_CHECKS = 1");
    }
  });
}

async function seedLookups(db: Db): Promise<void> {
  await db
    .insert(billStatuses)
    .values(STATUS_DEFAULTS.map((s, i) => ({ name: s.name, color: s.color, emoji: s.emoji, isSettled: s.isSettled, sortOrder: i })))
    .onDuplicateKeyUpdate({ set: { emoji: sql`COALESCE(emoji, VALUES(emoji))` } });
  await db
    .insert(paymentTypes)
    .values(PAYMENT_TYPE_DEFAULTS.map((p, i) => ({ name: p.name, color: p.color, emoji: p.emoji, sortOrder: i })))
    .onDuplicateKeyUpdate({ set: { emoji: sql`COALESCE(emoji, VALUES(emoji))` } });
  await db
    .insert(categories)
    .values(CATEGORY_DEFAULTS.map((c, i) => ({ name: c.name, color: c.color, emoji: c.emoji, sortOrder: i })))
    .onDuplicateKeyUpdate({ set: { emoji: sql`COALESCE(emoji, VALUES(emoji))` } });
}

// ---- the simulation --------------------------------------------------------------------------

export interface Snapshot {
  acct: AcctKey;
  asOf: string;
  balance: number;
  note: string;
}

export interface Simulation {
  months: { year: number; month: number; label: string; start: string; end: string }[];
  txns: Tx[];
  snapshots: Snapshot[];
  /** bill name → label of the month → the key of the transaction that paid it. */
  paidBy: Map<string, Map<string, string>>;
  /** Amount due per bill per month (utilities vary). */
  billAmount: Map<string, Map<string, number>>;
  pastDueBill: string | null;
  paydaysByMonth: Map<string, number>;
  final: Record<AcctKey, number>;
  /** Ledger balances for the Demo Bank token: holds from yesterday not yet included. */
  bankLedger: { checking: number; card: number };
  feedStart: string;
  carValue: { asOf: string; value: number }[];
}

/** The pure half of the seed: what would be written for `today`. Exported for tests. */
export function simulateDemo(today: string): Simulation {
  const [ty, tm, td] = today.split("-").map(Number);
  const months: Simulation["months"] = [];
  for (let back = 6; back >= 0; back--) {
    const zero = ty * 12 + (tm - 1) - back;
    const year = Math.floor(zero / 12);
    const month = (zero % 12) + 1;
    months.push({ year, month, label: periodLabel(year, month), ...monthBounds(year, month) });
  }
  const current = months[months.length - 1];
  const start = months[0].start;
  // The last few days of card swipes come in "through the bank" rather than a CSV import.
  const feedStart = addDays(today, -3);

  const r = rngFor(`seed|${today}`);
  const between = (lo: number, hi: number) => round2(lo + r() * (hi - lo));

  const bal: Record<AcctKey, number> = {
    checking: ACCOUNT_DEFS.checking.start,
    savings: ACCOUNT_DEFS.savings.start,
    wallet: ACCOUNT_DEFS.wallet.start,
    cardA: ACCOUNT_DEFS.cardA.start,
    cardB: ACCOUNT_DEFS.cardB.start,
    loan: ACCOUNT_DEFS.loan.start,
    retirement: ACCOUNT_DEFS.retirement.start,
  };
  const pendingHolds = { checking: 0, cardA: 0 };
  const txns: Tx[] = [];
  const snapshots: Snapshot[] = [];
  const paidBy = new Map<string, Map<string, string>>();
  const billAmount = new Map<string, Map<string, number>>();
  let n = 0;

  const post = (t: Omit<Tx, "key" | "source"> & { source?: string }): string => {
    const key = `t${++n}`;
    txns.push({ source: "import", ...t, key });
    const liability = t.acct === "cardA" || t.acct === "cardB";
    const delta = (t.direction === "Credit") !== liability ? t.amount : -t.amount;
    bal[t.acct] = round2(bal[t.acct] + delta);
    return key;
  };
  const snapshotAll = (asOf: string, note: string) => {
    for (const acct of Object.keys(ACCOUNT_DEFS) as AcctKey[]) {
      // A card's recorded balance is what has posted; holds from the last day aren't on it yet.
      const held = acct === "cardA" ? pendingHolds.cardA : 0;
      snapshots.push({ acct, asOf, balance: round2(bal[acct] - held), note });
    }
  };

  // Which bill is running late this month: the most recently due non-debt, non-autopay bill.
  const lateCandidates = BILL_DEFS.filter((b) => !b.debtOf && !b.autopay && b.name !== "Rent" && b.dueDay < td);
  const pastDueBill = lateCandidates.length ? lateCandidates[lateCandidates.length - 1].name : null;

  snapshotAll(addDays(start, -1), "Opening balance");

  for (const day of eachDay(start, today)) {
    const [y, m, d] = day.split("-").map(Number);
    const label = periodLabel(y, m);
    const isCurrentMonth = label === current.label;
    const monthEnd = monthBounds(y, m).end;

    // Payday (and the 401(k) contribution that comes out before it lands).
    if ((isoToMs(day) - isoToMs(PAY_ANCHOR)) % (14 * 86_400_000) === 0) {
      post({ acct: "checking", date: day, description: "ACME CORP PAYROLL DIR DEP", amount: TAKE_HOME, direction: "Credit", category: "Deposit", ruleCategorized: true });
      bal.retirement = round2(bal.retirement + 310);
    }

    // Early each month: move money to savings.
    if (d === 2) {
      const out = post({ acct: "checking", date: day, description: "ONLINE TRANSFER TO SAVINGS 2222", amount: SAVINGS_TRANSFER, direction: "Debit", category: "Transfer" });
      const inn = post({ acct: "savings", date: day, description: "ONLINE TRANSFER FROM CHECKING 1111", amount: SAVINGS_TRANSFER, direction: "Credit", category: "Transfer", partnerKey: out });
      txns.find((t) => t.key === out)!.partnerKey = inn;
    }

    // Bills.
    for (const b of BILL_DEFS) {
      if (b.dueDay !== d) continue;
      const amount = b.varies ? round2(b.amount + (r() * 2 - 1) * b.varies) : b.amount;
      if (!billAmount.has(b.name)) billAmount.set(b.name, new Map());
      billAmount.get(b.name)!.set(label, amount);
      if (isCurrentMonth && b.name === pastDueBill) continue; // not paid yet
      const key = post({
        acct: b.payFrom,
        date: day,
        description: b.description,
        amount,
        direction: "Debit",
        category: b.category,
        ruleCategorized: RULE_DEFS.some((x) => b.description.includes(x.pattern)),
        bill: b.name,
      });
      if (!paidBy.has(b.name)) paidBy.set(b.name, new Map());
      paidBy.get(b.name)!.set(label, key);
      if (b.debtOf === "cardA" || b.debtOf === "cardB") {
        // The payment arriving on the card. An internal move, so it is not spending or income.
        post({ acct: b.debtOf, date: day, description: "PAYMENT RECEIVED - THANK YOU", amount, direction: "Credit", category: "Transfer" });
      } else if (b.debtOf === "loan") {
        const interest = round2((bal.loan * LOAN_FACTS.apr) / 1200);
        bal.loan = round2(bal.loan - (amount - interest));
      }
    }

    // Cash: one ATM withdrawal a month, and what it paid for.
    if (d === 8) {
      post({ acct: "checking", date: day, description: "ATM WITHDRAWAL ANYTOWN CA", amount: 80, direction: "Debit", category: "Cash", ruleCategorized: true });
      bal.wallet = round2(bal.wallet + 80);
    }
    if (d === 10) post({ acct: "wallet", date: day, description: "Farmers market", amount: 24, direction: "Debit", category: "Food/Groceries", source: "manual" });
    if (d === 17) post({ acct: "wallet", date: day, description: "Barber", amount: 30, direction: "Debit", category: "Essentials", source: "manual" });
    if (d === 23) {
      // Cash that left the wallet without a receipt — the "unaccounted" part of the withdrawal.
      bal.wallet = round2(bal.wallet - 16);
    }

    // A monthly warehouse run on the card.
    if (d === 6) {
      post({ acct: "cardA", date: day, description: "BIG BOX SUPERSTORE #55", amount: between(84, 132), direction: "Debit", category: "Food/Groceries", ruleCategorized: true });
    }

    // Interest.
    if (d === 27) {
      for (const card of ["cardA", "cardB"] as const) {
        post({
          acct: card,
          date: day,
          description: "INTEREST CHARGE ON PURCHASES",
          amount: round2((bal[card] * CARD_FACTS[card].apr) / 1200),
          direction: "Debit",
          category: "Interest",
          ruleCategorized: true,
        });
      }
    }
    if (day === monthEnd) {
      post({ acct: "savings", date: day, description: "INTEREST PAYMENT", amount: round2((bal.savings * 4.1) / 1200), direction: "Credit", category: "Interest/Rewards", ruleCategorized: true });
      bal.retirement = round2(bal.retirement * (1 + (0.004 + r() * 0.006)));
    }

    // Card swipes: the Demo Bank feed. Older days arrived by CSV import; the last few came in
    // through bank sync, and today's are left for the next "Sync now".
    if (day < today) {
      for (const kind of ["checking", "card"] as const) {
        const acct: AcctKey = kind === "checking" ? "checking" : "cardA";
        for (const item of demoFeed(kind, day)) {
          const rule = RULE_DEFS.find((x) => item.description.includes(x.pattern));
          const hand = HAND_CATEGORIES.find((x) => item.description.includes(x.pattern));
          const recent = day >= addDays(today, -UNCATEGORIZED_WINDOW_DAYS);
          const synced = day >= feedStart;
          const pending = synced && demoIsPending(day, today);
          post({
            acct,
            date: day,
            description: item.description,
            amount: item.amount,
            direction: item.direction,
            category: rule ? rule.category : hand && !recent ? hand.category : null,
            ruleCategorized: !!rule,
            ...(synced
              ? {
                  source: DEMO_PROVIDER_ID,
                  externalId: item.externalId,
                  pending,
                  raw: {
                    provider: { demo: true, id: item.externalId },
                    seen: { txnDate: day, description: item.description, amount: item.amount, direction: item.direction, status: pending ? "pending" : "posted" },
                  },
                }
              : {}),
          });
          if (pending) pendingHolds[kind === "checking" ? "checking" : "cardA"] += item.amount;
        }
      }
    }

    if (day === monthEnd && day !== today) snapshotAll(day, "Month-end balance");
  }

  // A few rows nobody has dealt with yet, so the review screens have real work on them.
  post({ acct: "checking", date: addDays(today, -12), description: "MOBILE DEPOSIT", amount: 120, direction: "Credit", category: null });
  post({ acct: "checking", date: addDays(today, -9), description: "CHECK #1042", amount: 60, direction: "Debit", category: null });
  post({ acct: "cardB", date: addDays(today, -15), description: "ANNUAL MEMBERSHIP RENEWAL", amount: 49, direction: "Debit", category: null });
  post({ acct: "cardA", date: addDays(today, -6), description: "PARKING METER 0042 ANYTOWN", amount: 3.5, direction: "Debit", category: null });
  // Hand-entered placeholder for a payment the bank hasn't seen yet.
  post({
    acct: "checking",
    date: today,
    description: "Dentist copay",
    amount: 40,
    direction: "Debit",
    category: "Essentials",
    source: "manual",
    pending: true,
    notes: "Paid at the front desk — waiting for it to post.",
  });

  snapshotAll(today, "Balance today");

  // The car loses a little value every month.
  const carValue = months.map((mo, i) => ({ asOf: i === months.length - 1 ? today : mo.end, value: round2(16800 - i * 165) }));
  carValue.unshift({ asOf: addDays(start, -1), value: 16965 });

  return {
    months,
    txns,
    snapshots,
    paidBy,
    billAmount,
    pastDueBill,
    paydaysByMonth: countPaydays(months),
    final: bal,
    bankLedger: { checking: round2(bal.checking + pendingHolds.checking + 40), card: round2(bal.cardA - pendingHolds.cardA) },
    feedStart,
    carValue,
  };
}

function countPaydays(months: Simulation["months"]): Map<string, number> {
  const out = new Map<string, number>();
  for (const mo of months) {
    let c = 0;
    for (const day of eachDay(mo.start, mo.end)) if ((isoToMs(day) - isoToMs(PAY_ANCHOR)) % (14 * 86_400_000) === 0) c++;
    out.set(mo.label, c);
  }
  return out;
}

// ---- writing it down -------------------------------------------------------------------------

async function insertChunks<T>(rows: T[], size: number, write: (chunk: T[]) => Promise<unknown>): Promise<void> {
  for (let i = 0; i < rows.length; i += size) await write(rows.slice(i, i + size));
}

export async function seedDemo(conn: Connection | Pool, opts: SeedDemoOptions = {}): Promise<SeedDemoResult> {
  const today = opts.today ?? todayLocal();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) throw new Error(`seedDemo: today must be YYYY-MM-DD, got "${today}"`);
  const db = drizzle(conn as Pool, { schema, mode: "default" });

  if (opts.reset) {
    await resetData(conn);
  } else {
    const [[t], [a]] = await Promise.all([
      db.select({ c: sql<number>`COUNT(*)` }).from(transactions),
      db.select({ c: sql<number>`COUNT(*)` }).from(accounts),
    ]);
    if (Number(t.c) > 0 || Number(a.c) > 0) {
      throw new Error("seedDemo: this database already holds accounts or transactions. Pass { reset: true } to replace them with the demo data.");
    }
  }
  await seedLookups(db);

  const sim = simulateDemo(today);
  const current = sim.months[sim.months.length - 1];
  const previous = sim.months[sim.months.length - 2];

  // ---- periods, bills, accounts ----
  // Upsert: on a fresh install the app has usually already created this month and the next.
  await db
    .insert(periods)
    .values(sim.months.map((m) => ({ year: m.year, month: m.month, label: m.label, startDate: m.start, endDate: m.end })))
    .onDuplicateKeyUpdate({ set: { label: sql`VALUES(label)` } });
  const periodId = new Map((await db.select({ id: periods.id, label: periods.label }).from(periods)).map((p) => [p.label, p.id]));

  await db.insert(bills).values(
    BILL_DEFS.map((b) => ({
      name: b.name,
      defaultAmount: money(b.amount),
      defaultDueDay: b.dueDay,
      defaultPaymentType: b.paymentType,
      category: b.category,
      isDebt: !!b.debtOf,
    })),
  );
  const billId = new Map((await db.select({ id: bills.id, name: bills.name }).from(bills)).map((b) => [b.name, b.id]));
  const billOfDebt = new Map(BILL_DEFS.filter((b) => b.debtOf).map((b) => [b.debtOf!, b.name]));

  await db.insert(accounts).values(
    (Object.keys(ACCOUNT_DEFS) as AcctKey[]).map((k) => {
      const a = ACCOUNT_DEFS[k];
      const debtBill = billOfDebt.get(k as "cardA" | "cardB" | "loan");
      return {
        accountNumber: a.number,
        label: a.label,
        institution: a.institution,
        accountType: a.type,
        originalPrincipal: k === "loan" ? money(LOAN_FACTS.original) : null,
        openedOn: k === "loan" ? addDays(sim.months[0].start, -820) : null,
        billId: debtBill ? billId.get(debtBill)! : null,
      };
    }),
  );
  const accountRows = await db.select({ id: accounts.id, n: accounts.accountNumber }).from(accounts);
  const accountId = (k: AcctKey) => accountRows.find((r) => r.n === ACCOUNT_DEFS[k].number)!.id;

  // ---- bill sheets ----
  const instanceRows: (typeof billInstances.$inferInsert)[] = [];
  for (const mo of sim.months) {
    const isCurrent = mo.label === current.label;
    let nextUnpaidMarked = false;
    BILL_DEFS.forEach((b, i) => {
      const paid = sim.paidBy.get(b.name)?.has(mo.label) ?? false;
      let status: string;
      if (paid) status = b.autopay ? "Autopay" : "Paid/Purchased";
      else if (isCurrent && b.name === sim.pastDueBill) status = "Past Due";
      else if (b.autopay) status = "Autopay";
      else if (!nextUnpaidMarked && !b.debtOf) {
        status = "Ready for Payment";
        nextUnpaidMarked = true;
      } else status = "Not Due Yet";
      instanceRows.push({
        periodId: periodId.get(mo.label)!,
        billId: billId.get(b.name)!,
        name: b.name,
        // A bill that hasn't come due this month shows the usual amount, not a made-up actual.
        amount: money(sim.billAmount.get(b.name)?.get(mo.label) ?? b.amount),
        status,
        dueDay: b.dueDay,
        paymentType: b.paymentType,
        isDebt: !!b.debtOf,
        sortOrder: i,
      });
    });
  }
  await db.insert(billInstances).values(instanceRows);
  const instanceId = new Map(
    (await db.select({ id: billInstances.id, periodId: billInstances.periodId, billId: billInstances.billId }).from(billInstances)).map((r) => [`${r.periodId}|${r.billId}`, r.id]),
  );

  // ---- rules ----
  await db.insert(categoryMappings).values(
    RULE_DEFS.map((x, i) => ({
      matchType: "contains",
      pattern: x.pattern,
      field: "description",
      category: x.category,
      billId: x.bill ? billId.get(x.bill)! : null,
      priority: 100 + i,
    })),
  );
  const ruleRows = await db.select({ id: categoryMappings.id, pattern: categoryMappings.pattern }).from(categoryMappings);
  const ruleIdFor = (description: string) => {
    const def = RULE_DEFS.find((x) => description.includes(x.pattern));
    return def ? (ruleRows.find((x) => x.pattern === def.pattern)?.id ?? null) : null;
  };

  // ---- import batches (the CSV files this history "came from") ----
  const batchKeys = new Map<string, { acct: AcctKey; label: string; count: number }>();
  for (const t of sim.txns) {
    if (t.source !== "import") continue;
    const label = t.date.slice(0, 7);
    const k = `${t.acct}|${label}`;
    const cur = batchKeys.get(k) ?? { acct: t.acct, label, count: 0 };
    cur.count++;
    batchKeys.set(k, cur);
  }
  const batchList = [...batchKeys.values()].sort((a, b) => a.label.localeCompare(b.label) || a.acct.localeCompare(b.acct));
  await db.insert(importBatches).values(
    batchList.map((b) => ({
      filename: `${ACCOUNT_DEFS[b.acct].label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${b.label}.csv`,
      source: "csv",
      accountId: accountId(b.acct),
      totalRows: b.count,
      insertedCount: b.count,
      duplicateCount: 0,
      errorCount: 0,
      createdAt: at(b.label === current.label ? today : monthBounds(Number(b.label.slice(0, 4)), Number(b.label.slice(5))).end, 19),
    })),
  );
  const batchRows = await db.select({ id: importBatches.id, filename: importBatches.filename }).from(importBatches);
  const batchId = (acct: AcctKey, label: string) =>
    batchRows.find((b) => b.filename === `${ACCOUNT_DEFS[acct].label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${label}.csv`)?.id ?? null;

  // ---- transactions ----
  const sorted = [...sim.txns].sort((a, b) => a.date.localeCompare(b.date) || Number(a.key.slice(1)) - Number(b.key.slice(1)));
  const contentHashes = hashRows(
    sorted.map((t) => ({ accountNumber: ACCOUNT_DEFS[t.acct].number, date: t.date, amount: t.amount, description: t.description, direction: t.direction })),
  );
  const hashOf = new Map<string, string>();
  const txnRows = sorted.map((t, i) => {
    const label = t.date.slice(0, 7);
    const pid = periodId.get(label) ?? null;
    // Synced rows are keyed by the provider's id, exactly as the sync writer does it.
    const hash = t.externalId ? createHash("sha256").update(`${t.source}|${t.externalId}`).digest("hex") : contentHashes[i];
    hashOf.set(t.key, hash);
    const bId = t.bill ? billId.get(t.bill)! : null;
    return {
      accountId: accountId(t.acct),
      periodId: pid,
      billId: bId,
      billInstanceId: bId != null && pid != null ? (instanceId.get(`${pid}|${bId}`) ?? null) : null,
      txnDate: t.date,
      description: t.description,
      notes: t.notes ?? null,
      category: t.category,
      categoryRuleId: t.ruleCategorized ? ruleIdFor(t.description) : null,
      amount: money(t.amount),
      netAmount: null,
      direction: t.direction,
      dedupHash: hash,
      importBatchId: t.source === "import" ? batchId(t.acct, label) : null,
      raw: t.raw ?? null,
      source: t.source,
      externalId: t.externalId ?? null,
      pending: !!t.pending,
      status: t.pending ? "pending" : "posted",
      createdAt: at(t.date, 20),
    } satisfies typeof transactions.$inferInsert;
  });
  await insertChunks(txnRows, 200, (chunk) => db.insert(transactions).values(chunk));
  const idByHash = new Map((await db.select({ id: transactions.id, h: transactions.dedupHash }).from(transactions)).map((x) => [x.h, x.id]));
  const txnId = (key: string) => idByHash.get(hashOf.get(key)!)!;

  // Transfer pairs point at each other.
  for (const t of sim.txns) {
    if (t.partnerKey) await db.update(transactions).set({ transferPartnerId: txnId(t.partnerKey) }).where(eq(transactions.id, txnId(t.key)));
  }

  // Card payments are filed as Debt Repayment (so the budget's debt lines see them), not as
  // transfers, and the Transfers screen would offer each one as a pair forever. Dismiss the
  // old ones; the latest month's stay as live suggestions.
  const payments = sim.txns.filter((t) => t.bill === "Card A" || t.bill === "Card B");
  const dismissals: { lowId: number; highId: number }[] = [];
  for (const p of payments) {
    if (p.date.slice(0, 7) === current.label || p.date.slice(0, 7) === previous.label) continue;
    const landing = sim.txns.find(
      (t) => t.description === "PAYMENT RECEIVED - THANK YOU" && t.date === p.date && t.amount === p.amount && t.acct === (p.bill === "Card A" ? "cardA" : "cardB"),
    );
    if (!landing) continue;
    const [a, b] = [txnId(p.key), txnId(landing.key)];
    dismissals.push({ lowId: Math.min(a, b), highId: Math.max(a, b) });
  }
  if (dismissals.length) await db.insert(transferDismissals).values(dismissals);

  // Cash offsets: each wallet purchase is paid for by that month's ATM withdrawal.
  const allocations: (typeof cashAllocations.$inferInsert)[] = [];
  for (const mo of sim.months) {
    const withdrawal = sim.txns.find((t) => t.description.startsWith("ATM WITHDRAWAL") && t.date.startsWith(mo.label));
    if (!withdrawal) continue;
    for (const spend of sim.txns.filter((t) => t.acct === "wallet" && t.date.startsWith(mo.label))) {
      allocations.push({ withdrawalTxnId: txnId(withdrawal.key), spendTxnId: txnId(spend.key), amount: money(spend.amount) });
    }
  }
  if (allocations.length) await db.insert(cashAllocations).values(allocations);

  // One split: the latest warehouse run was part groceries, part household.
  const warehouse = [...sim.txns].reverse().find((t) => t.description.startsWith("BIG BOX SUPERSTORE"));
  if (warehouse) {
    await db.insert(transactionSplits).values({ txnId: txnId(warehouse.key), category: "Essentials", amount: money(38) });
    await db.update(transactions).set({ notes: "Paper goods and cleaning supplies were about $38 of this." }).where(eq(transactions.id, txnId(warehouse.key)));
  }

  // ---- balance history ----
  const balanceRows = sim.snapshots.map((s) => {
    const card = s.acct === "cardA" || s.acct === "cardB" ? CARD_FACTS[s.acct] : null;
    return {
      accountId: accountId(s.acct),
      balance: money(s.balance),
      creditLimit: card ? money(card.limit) : null,
      apr: card ? card.apr.toFixed(2) : s.acct === "loan" ? LOAN_FACTS.apr.toFixed(2) : null,
      minPayment: card ? money(card.min) : s.acct === "loan" ? money(LOAN_FACTS.payment) : null,
      asOf: s.asOf,
      note: s.acct === "wallet" ? "Counted" : s.note,
      createdAt: at(s.asOf, 21),
    } satisfies typeof accountBalances.$inferInsert;
  });
  await insertChunks(balanceRows, 200, (chunk) => db.insert(accountBalances).values(chunk));

  // ---- assets ----
  await db.insert(assets).values([
    { name: "Sedan", kind: "vehicle", purchasePrice: money(22400), acquiredOn: addDays(sim.months[0].start, -820), notes: "Financed with the auto loan." },
    { name: "Work laptop", kind: "equipment", purchasePrice: money(1450), acquiredOn: addDays(sim.months[0].start, -200) },
  ]);
  const assetRows = await db.select({ id: assets.id, name: assets.name }).from(assets);
  const assetIdOf = (name: string) => assetRows.find((a) => a.name === name)!.id;
  await db.insert(assetValues).values([
    ...sim.carValue.map((v) => ({ assetId: assetIdOf("Sedan"), value: money(v.value), asOf: v.asOf, note: "Estimated resale value" })),
    { assetId: assetIdOf("Work laptop"), value: money(1100), asOf: addDays(sim.months[0].start, -1), note: null },
    { assetId: assetIdOf("Work laptop"), value: money(900), asOf: today, note: null },
  ]);

  // ---- pay schedule ----
  await db.insert(paySchedule).values({
    frequency: "biweekly",
    anchorDate: PAY_ANCHOR,
    takeHome: money(TAKE_HOME),
    depositWindowDays: 3,
    notes: "Every other Friday by direct deposit.",
  });

  // ---- budgets: last month and this one ----
  const budgetLineDefs = [
    { kind: "debt", label: ACCOUNT_DEFS.cardA.label, acct: "cardA" as AcctKey, planned: CARD_A_PAYMENT, minimum: CARD_FACTS.cardA.min, isTarget: true },
    { kind: "debt", label: ACCOUNT_DEFS.cardB.label, acct: "cardB" as AcctKey, planned: CARD_B_PAYMENT, minimum: CARD_FACTS.cardB.min },
    { kind: "debt", label: ACCOUNT_DEFS.loan.label, acct: "loan" as AcctKey, planned: LOAN_FACTS.payment, minimum: LOAN_FACTS.payment },
    { kind: "category", label: "Rent", category: "Rent", planned: 1450 },
    { kind: "category", label: "Food/Groceries", category: "Food/Groceries", planned: FOOD_PLAN },
    { kind: "category", label: "Utilities", category: "Utilities", planned: 215 },
    { kind: "category", label: "Transportation", category: "Transportation", planned: 320 },
    { kind: "category", label: "Discretionary", category: "Discretionary", planned: 220 },
    { kind: "category", label: "Essentials", category: "Essentials", planned: 120 },
    { kind: "savings", label: "Savings", category: "Savings", planned: SAVINGS_TRANSFER },
  ];
  for (const mo of [previous, current]) {
    await db.insert(budgets).values({
      periodId: periodId.get(mo.label)!,
      mode: "debt_snowball",
      strategy: "avalanche",
      plannedIncome: money((sim.paydaysByMonth.get(mo.label) ?? 2) * TAKE_HOME),
      autoRebalance: false,
      notes: mo.label === current.label ? "Everything left after the essentials goes at Card A, the highest-APR balance." : null,
    });
    const [b] = await db.select({ id: budgets.id }).from(budgets).where(eq(budgets.periodId, periodId.get(mo.label)!)).limit(1);
    await db.insert(budgetLines).values(
      budgetLineDefs.map((l, i) => ({
        budgetId: b.id,
        kind: l.kind,
        label: l.label,
        category: l.category ?? null,
        accountId: l.acct ? accountId(l.acct) : null,
        planned: money(l.planned),
        minimum: l.minimum != null ? money(l.minimum) : null,
        isTarget: !!l.isTarget,
        locked: true,
        sortOrder: i,
      })),
    );
  }

  // ---- savings goals ----
  await db.insert(savingsGoals).values([
    {
      name: "Emergency fund",
      goalType: "savings",
      targetAmount: money(10000),
      fundingAccountId: accountId("savings"),
      color: "#10b981",
      emoji: "🛟",
      sortOrder: 0,
      notes: "Four months of expenses. Off-limits for anything else.",
    },
    {
      name: "Coast trip",
      goalType: "purchase",
      targetAmount: money(1800),
      targetDate: addDays(today, 240),
      fundingAccountId: accountId("savings"),
      color: "#3b82f6",
      emoji: "🏖️",
      sortOrder: 1,
    },
    {
      name: "Pay off Card B",
      goalType: "debt_payoff",
      targetAmount: money(ACCOUNT_DEFS.cardB.start),
      fundingAccountId: accountId("cardB"),
      color: "#f97316",
      emoji: "💳",
      sortOrder: 2,
    },
  ]);
  const goalRows = await db.select({ id: savingsGoals.id, name: savingsGoals.name }).from(savingsGoals);
  const goalIdOf = (name: string) => goalRows.find((g) => g.name === name)!.id;
  const contributions: (typeof goalContributions.$inferInsert)[] = [
    { goalId: goalIdOf("Emergency fund"), amount: money(ACCOUNT_DEFS.savings.start), occurredOn: addDays(sim.months[0].start, -1), note: "Already saved when tracking started" },
  ];
  for (const t of sim.txns) {
    if (t.acct === "savings" && t.description.startsWith("ONLINE TRANSFER FROM")) {
      contributions.push({ goalId: goalIdOf("Emergency fund"), amount: money(225), occurredOn: t.date, note: "Monthly transfer", transactionId: txnId(t.key) });
      contributions.push({ goalId: goalIdOf("Coast trip"), amount: money(75), occurredOn: t.date, note: "Monthly transfer", transactionId: txnId(t.key) });
    }
    if (t.bill === "Card B") {
      contributions.push({ goalId: goalIdOf("Pay off Card B"), amount: money(t.amount), occurredOn: t.date, note: "Monthly payment", transactionId: txnId(t.key) });
    }
  }
  await db.insert(goalContributions).values(contributions);

  // ---- advisor: a profile, a finished insights run, a check-in and one conversation ----
  const upsertSetting = (settingKey: string, value: unknown) =>
    db.insert(appSettings).values({ settingKey, value }).onDuplicateKeyUpdate({ set: { value } });
  await upsertSetting("advisor_profile", {
    name: "Alex",
    updatedOn: today,
    situation: [
      `Salaried at ACME Corp, about $${TAKE_HOME.toLocaleString("en-US")} take-home every other Friday by direct deposit.`,
      "Renting in Anytown at $1,450/mo.",
      "Two credit cards carrying a balance and an auto loan with about three years left.",
    ],
    plan: [
      "Emergency fund: build to $10,000 in the savings account. Off-limits for anything else.",
      "Debt: avalanche. Everything left after the essentials goes to Card A (highest APR); Card B and the auto loan stay near their minimums.",
      `Keep food spending near $${FOOD_PLAN}/mo — it is the category that drifts.`,
    ],
    dataCaveats: [
      "This is generated sample data for the demo; none of it is a real person's finances.",
      "Amounts are USD dollars (numbers, 2dp). Dates are ISO YYYY-MM-DD; periods are YYYY-MM.",
    ],
    advisorStyle: [
      "Act like a fee-only financial planner who already knows the client: concrete numbers, trade-offs, and a recommendation — not generic tips.",
      "Ground every claim in tool data; when data is missing or stale, say what you'd need.",
      "Before any write tool, state exactly what will change and wait for confirmation.",
    ],
  });

  const coffee = sim.txns.filter((t) => t.description.startsWith("SUNRISE COFFEE") && t.date.startsWith(previous.label));
  const coffeeTotal = round2(coffee.reduce((s, t) => s + t.amount, 0));
  const interestLast = round2(sim.txns.filter((t) => t.category === "Interest" && t.date.startsWith(previous.label)).reduce((s, t) => s + t.amount, 0));
  const foodLast = round2(
    sim.txns.filter((t) => t.category === "Food/Groceries" && t.direction === "Debit" && t.date.startsWith(previous.label)).reduce((s, t) => s + t.amount, 0),
  );
  const foodOver = foodLast > FOOD_PLAN;
  await db.insert(advisorRuns).values([
    {
      kind: "insights",
      trigger: "app",
      status: "ok",
      routine: "MiPlata advisor",
      summary: "Looked across the last three months and saved 5 findings.",
      insightsSaved: 5,
      startedAt: at(addDays(today, -2), 9),
      finishedAt: at(addDays(today, -2), 10),
    },
    {
      kind: "checkin",
      trigger: "cron",
      status: "ok",
      routine: "MiPlata advisor",
      summary: "Daily check-in",
      report: [
        `**Where you stand.** Checking is at $${sim.final.checking.toLocaleString("en-US", { minimumFractionDigits: 2 })} and the next paycheck is on its way.`,
        "",
        sim.pastDueBill ? `- **${sim.pastDueBill}** is past due — pay it before anything else.` : "- No bills are past due.",
        `- Card A is your target debt this month: $${CARD_A_PAYMENT} planned against it.`,
        "- Food spending is the line to watch; restaurants are what move it.",
        "",
        "Nothing needs a decision today.",
      ].join("\n"),
      startedAt: at(today, 7),
      finishedAt: at(today, 7),
    },
  ]);
  const runRows = await db.select({ id: advisorRuns.id, kind: advisorRuns.kind }).from(advisorRuns);
  const insightsRunId = runRows.find((x) => x.kind === "insights")!.id;
  await db.insert(advisorInsights).values([
    {
      dedupeKey: "demo-interest-cost",
      category: "debt",
      severity: "act",
      title: "Card interest is costing more than your streaming, gym and phone combined",
      body: `Card A and Card B charged **$${interestLast.toFixed(2)}** in interest last month. Every extra $100 toward Card A saves about $2 a month from then on — it is the best guaranteed return you have.`,
      amount: money(interestLast),
      periodLabel: previous.label,
      search: "INTEREST CHARGE",
      runId: insightsRunId,
      createdAt: at(addDays(today, -2), 10),
      lastSeenAt: at(addDays(today, -2), 10),
    },
    {
      dedupeKey: "demo-coffee-habit",
      category: "habit",
      severity: "watch",
      title: "The daily coffee adds up",
      body: `${coffee.length} visits to Sunrise Coffee last month came to **$${coffeeTotal.toFixed(2)}**. Not a problem by itself, but it is a fifth of the food budget before any groceries.`,
      amount: money(coffeeTotal),
      periodLabel: previous.label,
      search: "SUNRISE COFFEE",
      runId: insightsRunId,
      createdAt: at(addDays(today, -2), 10),
      lastSeenAt: at(addDays(today, -2), 10),
    },
    {
      dedupeKey: "demo-food-vs-plan",
      category: "budget",
      severity: foodOver ? "watch" : "info",
      title: foodOver ? "Food ran over plan last month" : "Food stayed inside the plan last month",
      body:
        `Food/Groceries came to **$${foodLast.toFixed(2)}** against a $${FOOD_PLAN} plan. ` +
        (foodOver ? "Restaurants, not groceries, made the difference." : "Restaurants are the part that swings month to month."),
      amount: money(Math.abs(foodLast - FOOD_PLAN)),
      periodLabel: previous.label,
      runId: insightsRunId,
      createdAt: at(addDays(today, -2), 10),
      lastSeenAt: at(addDays(today, -2), 10),
    },
    {
      dedupeKey: "demo-uncategorized",
      category: "data-quality",
      severity: "info",
      title: "A few recent transactions have no category",
      body: "A check, a mobile deposit and some payment-app transfers are uncategorized, so this month's totals are slightly understated. The Categorize screen clears them in a minute.",
      periodLabel: current.label,
      runId: insightsRunId,
      createdAt: at(addDays(today, -2), 10),
      lastSeenAt: at(addDays(today, -2), 10),
    },
    {
      dedupeKey: "demo-emergency-fund-pace",
      category: "savings",
      severity: "info",
      status: "seen",
      title: "The emergency fund is on a steady pace",
      body: "You have moved $300 to savings on the 2nd of every month without a miss. At this pace the $10,000 target is a little over two years out.",
      periodLabel: current.label,
      runId: insightsRunId,
      createdAt: at(addDays(today, -2), 10),
      lastSeenAt: at(addDays(today, -2), 10),
    },
  ]);
  await db.insert(advisorThreads).values({ title: "Can I afford a $900 laptop?", createdAt: at(addDays(today, -4), 18), updatedAt: at(addDays(today, -4), 18) });
  const [thread] = await db.select({ id: advisorThreads.id }).from(advisorThreads).limit(1);
  await db.insert(advisorMessages).values([
    {
      threadId: thread.id,
      role: "user",
      body: "Can I afford a $900 laptop this month without derailing the plan?",
      status: "answered",
      createdAt: at(addDays(today, -4), 18),
      answeredAt: at(addDays(today, -4), 18),
    },
    {
      threadId: thread.id,
      role: "assistant",
      body: [
        "Short answer: **yes, but not on Card A.**",
        "",
        "- Paying cash from checking leaves you above your usual low point before the next paycheck, with rent already covered.",
        "- Putting it on Card A at 24.99% and paying it off over six months would cost roughly $65 in interest and stall the payoff plan.",
        "- The emergency fund stays untouched either way.",
        "",
        "If you want it now, pay from checking and trim Discretionary for the rest of the month. If it can wait a paycheck, that is the cleaner option.",
      ].join("\n"),
      status: "answered",
      createdAt: at(addDays(today, -4), 18),
      answeredAt: at(addDays(today, -4), 18),
    },
  ]);

  // ---- bank sync: Demo Bank, already linked ----
  await db.insert(syncSettings).values({ id: 1 }).onDuplicateKeyUpdate({ set: { id: sql`id` } });
  let bankLinked = false;
  if (hasTokenKey()) {
    const token = encodeDemoToken({ seedDay: today, ledger: sim.bankLedger });
    await db.insert(syncEnrollments).values({
      provider: DEMO_PROVIDER_ID,
      enrollmentId: DEMO_ENROLLMENT_ID,
      institutionId: "demo-bank",
      institutionName: DEMO_INSTITUTION,
      accessTokenEnc: encryptToken(token),
      status: "active",
      enrolledAt: at(sim.feedStart, 9),
      lastSyncedAt: at(today, 6),
    });
    const [enr] = await db.select({ id: syncEnrollments.id }).from(syncEnrollments).where(eq(syncEnrollments.provider, DEMO_PROVIDER_ID)).limit(1);
    await db.insert(syncAccounts).values(
      (["checking", "card"] as const).map((kind) => ({
        enrollmentId: enr.id,
        externalAccountId: DEMO_ACCOUNTS[kind].externalId,
        name: DEMO_ACCOUNTS[kind].name,
        type: kind === "checking" ? "depository" : "credit",
        subtype: kind === "checking" ? "checking" : "credit_card",
        lastFour: DEMO_ACCOUNTS[kind].lastFour,
        currency: "USD",
        accountId: accountId(kind === "checking" ? "checking" : "cardA"),
        enabled: true,
        syncBalances: true,
        // History before this came in by CSV; the bank only fills in from here on.
        syncFrom: sim.feedStart,
        lastSyncedAt: at(today, 6),
      })),
    );
    const synced = (day: string) => sim.txns.filter((t) => t.source === DEMO_PROVIDER_ID && t.date === day).length;
    await db.insert(syncRuns).values(
      [2, 1, 0].map((ago) => {
        const day = addDays(today, -ago);
        const inserted = ago === 0 ? synced(addDays(today, -1)) : synced(addDays(day, -1));
        return {
          trigger: ago === 2 ? "manual" : "scheduled",
          enrollmentId: enr.id,
          status: "ok",
          startedAt: at(day, 6),
          finishedAt: at(day, 6),
          inserted,
          promoted: ago === 2 ? 0 : synced(addDays(day, -2)),
          balancesRecorded: 2,
          details: { enrollments: [] },
        };
      }),
    );
    const [lastRun] = await db.select({ id: sql<number>`MAX(${syncRuns.id})` }).from(syncRuns);
    await db
      .update(syncSettings)
      .set({ enabled: false, lockUntil: null, nextRunAt: null, lastRunId: lastRun.id, lastWebhookAt: null })
      .where(eq(syncSettings.id, 1));
    bankLinked = true;
  } else {
    await db.update(syncSettings).set({ enabled: false, lockUntil: null, nextRunAt: null, lastRunId: null, lastWebhookAt: null }).where(eq(syncSettings.id, 1));
    // Without the bank, the rows that "came in through sync" would point at a provider that
    // isn't linked. They are ordinary history, so file them as such.
    const demoIds = (await db.select({ id: transactions.id }).from(transactions).where(eq(transactions.source, DEMO_PROVIDER_ID))).map((x) => x.id);
    if (demoIds.length) {
      await db.update(transactions).set({ source: "manual", externalId: null, pending: false, status: "posted", raw: null }).where(inArray(transactions.id, demoIds));
    }
  }

  const [[txCount], [uncat], [pend]] = await Promise.all([
    db.select({ c: sql<number>`COUNT(*)` }).from(transactions),
    db.select({ c: sql<number>`COUNT(*)` }).from(transactions).where(sql`${transactions.category} IS NULL`),
    db.select({ c: sql<number>`COUNT(*)` }).from(transactions).where(ne(transactions.pending, false)),
  ]);

  return {
    summary: {
      today,
      months: sim.months.map((m) => m.label),
      accounts: accountRows.length,
      bills: BILL_DEFS.length,
      billInstances: instanceRows.length,
      transactions: Number(txCount.c),
      uncategorized: Number(uncat.c),
      pending: Number(pend.c),
      balanceSnapshots: balanceRows.length,
      rules: RULE_DEFS.length,
      budgets: 2,
      goals: goalRows.length,
      insights: 5,
      bankLinked,
    },
  };
}
